export interface Palette {
  readonly foreground: string;
  readonly surface: string;
  readonly accent: string;
}

export interface NavigationEntry {
  readonly label: string;
  readonly destination: string;
  readonly glyph: string;
}

export interface NavigationRow extends NavigationEntry, Palette {}

export const DEFAULT_PALETTE: Readonly<Palette> = Object.freeze({
  foreground: "#242424",
  surface: "#f7f7f7",
  accent: "#2962ff",
});

function requireText(value: string, field: string): void {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${field} must be non-blank`);
  }
}

export function buildNavigationRows(
  entries: readonly NavigationEntry[],
  palette: Palette = DEFAULT_PALETTE,
): readonly NavigationRow[] {
  requireText(palette.foreground, "foreground");
  requireText(palette.surface, "surface");
  requireText(palette.accent, "accent");

  const rows = entries.map((entry) => {
    requireText(entry.label, "label");
    requireText(entry.destination, "destination");
    requireText(entry.glyph, "glyph");
    return Object.freeze({
      label: entry.label,
      destination: entry.destination,
      glyph: entry.glyph,
      foreground: palette.foreground,
      surface: palette.surface,
      accent: palette.accent,
    });
  }).reverse();
  return Object.freeze(rows);
}

