import { DEFAULT_PALETTE, buildNavigationRows, type NavigationEntry, type Palette } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectTypeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

equal(DEFAULT_PALETTE.foreground, '#242424', 'default foreground');
equal(DEFAULT_PALETTE.surface, '#f7f7f7', 'default surface');
equal(DEFAULT_PALETTE.accent, '#2962ff', 'default accent');

const entries = [
  { label: '  Home  ', destination: '/same', glyph: ' H ' },
  { label: 'Second', destination: '/same', glyph: 'S' },
];
const palette = { foreground: ' fg ', surface: ' surface ', accent: ' accent ' };
const rows = buildNavigationRows(entries, palette);
equal(rows.length, 2, 'duplicate destinations remain separate');
equal(rows[0].label, '  Home  ', 'label is preserved');
equal(rows[0].destination, '/same', 'destination is preserved');
equal(rows[0].glyph, ' H ', 'glyph is preserved');
equal(rows[0].foreground, ' fg ', 'custom foreground is preserved');
equal(rows[0].surface, ' surface ', 'custom surface is preserved');
equal(rows[0].accent, ' accent ', 'custom accent is preserved');
equal(rows[1].label, 'Second', 'input order is preserved');
assert(Object.isFrozen(rows), 'returned array is frozen');
assert(Object.isFrozen(rows[0]) && Object.isFrozen(rows[1]), 'rows are frozen');

entries[0].label = 'changed';
entries[0].destination = '/changed';
entries.push({ label: 'Third', destination: '/third', glyph: 'T' });
palette.foreground = 'changed';
equal(rows.length, 2, 'result does not retain entries array');
equal(rows[0].label, '  Home  ', 'result copies entry fields');
equal(rows[0].destination, '/same', 'result is stable after entry mutation');
equal(rows[0].foreground, ' fg ', 'result copies palette fields');

const defaults = buildNavigationRows([{ label: 'A', destination: '/a', glyph: 'a' }]);
equal(defaults[0].foreground, '#242424', 'omitted palette uses default foreground');
equal(defaults[0].surface, '#f7f7f7', 'omitted palette uses default surface');
equal(defaults[0].accent, '#2962ff', 'omitted palette uses default accent');
const empty = buildNavigationRows([]);
equal(empty.length, 0, 'empty input returns empty output');
assert(Object.isFrozen(empty), 'empty output is frozen');

expectTypeError(() => buildNavigationRows([{ label: ' ', destination: '/a', glyph: 'a' }]), 'blank label');
expectTypeError(() => buildNavigationRows([{ label: 'a', destination: '\t', glyph: 'a' }]), 'blank destination');
expectTypeError(() => buildNavigationRows([{ label: 'a', destination: '/a', glyph: '' }]), 'blank glyph');
expectTypeError(() => buildNavigationRows([{ label: 3, destination: '/a', glyph: 'a' } as unknown as NavigationEntry]), 'non-string entry field');
expectTypeError(() => buildNavigationRows([], { foreground: ' ', surface: 'x', accent: 'x' }), 'blank palette field');
expectTypeError(() => buildNavigationRows([], { foreground: 'x', surface: 2, accent: 'x' } as unknown as Palette), 'non-string palette field');

